/// Renders the `improve` pipeline's end-to-end result -- the analyze → fix →
/// validate outcome for every module -- as human-readable reports.
///
/// Both generators are data-driven from the pipeline JSON the `improve`
/// command produces (see its `PipelineReport.toJson()`), keeping this package
/// decoupled from the CLI's orchestration types, exactly as the findings
/// reporters consume canonical findings JSON. The expected shape:
///
/// ```json
/// {
///   "project": "...", "mode": "module-wise", "generatedAt": "...",
///   "applied": false,
///   "totals": { "findingsBefore": 12, "findingsAfter": 4,
///               "fixesApplied": 0, "fixesProposed": 8, "fixesFailed": 0,
///               "modules": 3, "gatesPassed": true, "score": 88 },
///   "modules": [ {
///     "name": "...", "path": "...",
///     "before": [<finding>...], "after": [<finding>...],
///     "fixes": [ {"ruleId": "...", "file": "...", "diff": "..."} ],
///     "failed": [ {"ruleId": "...", "file": "...", "reason": "..."} ],
///     "validation": { "passed": true, "score": 88, "totalFindings": 4,
///                     "countsBySeverity": {...}, "failures": [...] }
///   } ]
/// }
/// ```
library;

/// Generates a single, self-contained HTML report from the pipeline JSON.
///
/// Everything (CSS included) is inlined; the file opens from disk with no
/// server or network access.
String generatePipelineHtmlReport(Map<String, dynamic> pipeline) {
  final totals = (pipeline['totals'] as Map?)?.cast<String, dynamic>() ?? {};
  final modules = (pipeline['modules'] as List?) ?? const [];
  final applied = pipeline['applied'] == true;
  final gatesPassed = totals['gatesPassed'] == true;
  final score = (totals['score'] as num?) ?? 0;

  final b = StringBuffer()
    ..writeln('<!doctype html>')
    ..writeln('<html lang="en"><head>')
    ..writeln('<meta charset="utf-8">')
    ..writeln('<meta name="viewport" content="width=device-width, initial-scale=1">')
    ..writeln('<title>CodeGuardian Improve Report</title>')
    ..writeln('<style>$_css</style>')
    ..writeln('</head><body>')
    ..writeln('<header class="hero">')
    ..writeln(
      '<div class="score" style="--c:${_scoreColor(score)}">'
      '${score.toStringAsFixed(0)}</div>',
    )
    ..writeln('<div>')
    ..writeln('<h1>CodeGuardian Improve Report</h1>')
    ..writeln(
      '<p class="meta">${_esc('${pipeline['project'] ?? ''}')} &middot; '
      '${_esc('${pipeline['mode'] ?? ''}')} &middot; '
      '${_esc('${pipeline['generatedAt'] ?? ''}')}</p>',
    )
    ..writeln('<div class="badges">')
    ..writeln(_badge(applied ? 'Fixes applied' : 'Dry run (preview)',
        applied ? 'ok' : 'warn'))
    ..writeln(_badge(gatesPassed ? 'Gates passed' : 'Gates failed',
        gatesPassed ? 'ok' : 'bad'))
    ..writeln('</div>')
    ..writeln('</div></header>');

  // Totals strip.
  b
    ..writeln('<section class="totals">')
    ..write(_stat('Modules', '${totals['modules'] ?? modules.length}'))
    ..write(_stat('Findings before', '${totals['findingsBefore'] ?? 0}'))
    ..write(_stat('Findings after', '${totals['findingsAfter'] ?? 0}'))
    ..write(_stat(applied ? 'Fixes applied' : 'Fixes proposed',
        '${totals[applied ? 'fixesApplied' : 'fixesProposed'] ?? 0}'))
    ..write(_stat('Fixes failed', '${totals['fixesFailed'] ?? 0}'))
    ..writeln('</section>')
    ..writeln('<main>');

  for (final raw in modules) {
    final m = (raw as Map).cast<String, dynamic>();
    b.write(_moduleSection(m, applied: applied));
  }

  b
    ..writeln('</main>')
    ..writeln('<footer>Generated by CodeGuardian AI</footer>')
    ..writeln('</body></html>');

  return b.toString();
}

String _moduleSection(Map<String, dynamic> m, {required bool applied}) {
  final before = (m['before'] as List?) ?? const [];
  final after = (m['after'] as List?) ?? const [];
  final fixes = (m['fixes'] as List?) ?? const [];
  final failed = (m['failed'] as List?) ?? const [];
  final validation =
      (m['validation'] as Map?)?.cast<String, dynamic>() ?? const {};
  final passed = validation['passed'] == true;

  final s = StringBuffer()
    ..writeln('<section class="module">')
    ..writeln('<h2>${_esc('${m['name'] ?? ''}')} '
        '<span class="chip ${passed ? 'ok' : 'bad'}">'
        '${passed ? 'gates passed' : 'gates failed'}</span></h2>')
    ..writeln('<p class="path">${_esc('${m['path'] ?? ''}')}</p>')
    ..writeln('<p class="delta">Findings: <b>${before.length}</b> &rarr; '
        '<b>${after.length}</b> &middot; '
        '${applied ? 'fixes applied' : 'fixes proposed'}: '
        '<b>${fixes.length}</b>'
        '${failed.isNotEmpty ? ' &middot; failed: <b>${failed.length}</b>' : ''}'
        '</p>');

  if (fixes.isNotEmpty) {
    s.writeln('<h3>${applied ? 'Applied' : 'Proposed'} fixes</h3>');
    for (final raw in fixes) {
      final f = (raw as Map).cast<String, dynamic>();
      s
        ..writeln('<details class="fix"><summary>'
            '<code>${_esc('${f['ruleId'] ?? ''}')}</code> '
            '${_esc('${f['file'] ?? ''}')}</summary>')
        ..writeln('<pre class="diff">${_diffHtml('${f['diff'] ?? ''}')}</pre>')
        ..writeln('</details>');
    }
  }

  if (failed.isNotEmpty) {
    s.writeln('<h3>Failed fixes</h3><ul class="failed">');
    for (final raw in failed) {
      final f = (raw as Map).cast<String, dynamic>();
      s.writeln('<li><code>${_esc('${f['ruleId'] ?? ''}')}</code> '
          '${_esc('${f['file'] ?? ''}')}: ${_esc('${f['reason'] ?? ''}')}</li>');
    }
    s.writeln('</ul>');
  }

  s.writeln('<h3>Remaining findings (${after.length})</h3>');
  if (after.isEmpty) {
    s.writeln('<p class="clean">No remaining findings &#127881;</p>');
  } else {
    s.writeln('<div class="table-scroll"><table>'
        '<thead><tr><th>Severity</th><th>Rule</th><th>File</th>'
        '<th>Line</th><th>Message</th></tr></thead><tbody>');
    for (final raw in after) {
      final f = (raw as Map).cast<String, dynamic>();
      final sev = '${f['severity'] ?? 'info'}';
      s.writeln('<tr>'
          '<td><span class="sev sev-$sev">${_esc(sev)}</span></td>'
          '<td><code>${_esc('${f['ruleId'] ?? ''}')}</code></td>'
          '<td>${_esc('${f['file'] ?? ''}')}</td>'
          '<td>${_esc('${f['line'] ?? ''}')}</td>'
          '<td>${_esc('${f['message'] ?? ''}')}</td>'
          '</tr>');
    }
    s.writeln('</tbody></table></div>');
  }

  final failures = (validation['failures'] as List?) ?? const [];
  if (failures.isNotEmpty) {
    s.writeln('<h3>Gate failures</h3><ul class="failed">');
    for (final raw in failures) {
      final g = (raw as Map).cast<String, dynamic>();
      s.writeln('<li>${_esc('${g['message'] ?? g['gate'] ?? ''}')}</li>');
    }
    s.writeln('</ul>');
  }

  s.writeln('</section>');
  return s.toString();
}

/// Generates a compact Markdown version of the same report (for PR comments
/// or a terminal-friendly summary).
String generatePipelineMarkdownReport(Map<String, dynamic> pipeline) {
  final totals = (pipeline['totals'] as Map?)?.cast<String, dynamic>() ?? {};
  final modules = (pipeline['modules'] as List?) ?? const [];
  final applied = pipeline['applied'] == true;

  final b = StringBuffer()
    ..writeln('# CodeGuardian Improve Report')
    ..writeln()
    ..writeln('- **Project:** ${pipeline['project'] ?? ''}')
    ..writeln('- **Mode:** ${pipeline['mode'] ?? ''}')
    ..writeln('- **Run:** ${applied ? 'fixes applied' : 'dry run (preview)'}')
    ..writeln('- **Score:** ${totals['score'] ?? 0} '
        '(${totals['gatesPassed'] == true ? 'gates passed' : 'gates failed'})')
    ..writeln('- **Findings:** ${totals['findingsBefore'] ?? 0} → '
        '${totals['findingsAfter'] ?? 0} · '
        '${applied ? 'applied' : 'proposed'} '
        '${totals[applied ? 'fixesApplied' : 'fixesProposed'] ?? 0} fix(es)')
    ..writeln();

  b.writeln('| Module | Before | After | Fixes | Gate |');
  b.writeln('|---|---:|---:|---:|:--:|');
  for (final raw in modules) {
    final m = (raw as Map).cast<String, dynamic>();
    final before = (m['before'] as List?)?.length ?? 0;
    final after = (m['after'] as List?)?.length ?? 0;
    final fixes = (m['fixes'] as List?)?.length ?? 0;
    final passed =
        ((m['validation'] as Map?)?['passed'] == true) ? '✅' : '❌';
    b.writeln('| ${m['name']} | $before | $after | $fixes | $passed |');
  }

  return b.toString();
}

String _stat(String label, String value) =>
    '<div class="stat"><span class="n">${_esc(value)}</span>'
    '<span class="l">${_esc(label)}</span></div>';

String _badge(String text, String kind) =>
    '<span class="badge $kind">${_esc(text)}</span>';

String _diffHtml(String diff) {
  final out = StringBuffer();
  for (final line in diff.split('\n')) {
    final cls = line.startsWith('+') && !line.startsWith('+++')
        ? 'add'
        : line.startsWith('-') && !line.startsWith('---')
            ? 'del'
            : line.startsWith('@@')
                ? 'hunk'
                : '';
    out.writeln('<span class="$cls">${_esc(line)}</span>');
  }
  return out.toString();
}

String _esc(String text) => text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');

String _scoreColor(num score) {
  if (score >= 90) return '#16a34a';
  if (score >= 70) return '#ca8a04';
  if (score >= 50) return '#ea580c';
  return '#dc2626';
}

const _css = '''
