.score{width:76px;height:76px;flex:0 0 76px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:700;color:#fff;background:var(--c)}
.badges{margin-top:10px;display:flex;gap:8px;flex-wrap:wrap}
