.badge.bad{background:#fee2e2;color:#991b1b}
.totals{display:flex;gap:16px;flex-wrap:wrap;padding:20px 32px;background:#fff;border-bottom:1px solid #e5e7eb}
.stat{display:flex;flex-direction:column}
.stat .n{font-size:24px;font-weight:700}
.stat .l{font-size:12px;color:#6b7280}
main{padding:24px 32px;max-width:1100px}
.module{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:20px 22px;margin-bottom:20px}
.module h2{margin:0 0 2px;font-size:18px;display:flex;align-items:center;gap:10px}
.module h3{margin:18px 0 8px;font-size:14px;text-transform:uppercase;letter-spacing:.04em;color:#6b7280}
.path{margin:0;color:#9ca3af;font-size:12px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}
.delta{margin:10px 0 0;font-size:14px}
.chip{font-size:11px;font-weight:600;padding:2px 8px;border-radius:999px}
.chip.ok{background:#dcfce7;color:#166534}
.chip.bad{background:#fee2e2;color:#991b1b}
